create table if not exists clqfa_follows (
 actor uuid references clqfa_profiles(id), target uuid references clqfa_profiles(id), created_at timestamptz default now(), primary key(actor,target), check(actor<>target)
)

create table if not exists clqfa_posts (
 id text primary key, author uuid not null references clqfa_profiles(id), type text not null check(type in ('text','images','video')), text text not null check(length(text)<=500), media jsonb not null default '[]', parent text references clqfa_posts(id), created_at timestamptz not null default clock_timestamp()
)

create or replace function clqfa_mutate(who uuid,op text,b jsonb) returns jsonb language plpgsql as $$
declare result jsonb; target_id uuid; c clqfa_chats%rowtype; m clqfa_messages%rowtype; a clqfa_media%rowtype; fresh boolean; pair_key text; ttl integer; window_config jsonb; msgtype text; media_id text;
begin
 if not exists(select 1 from clqfa_profiles where id=who) then raise exception 'Unknown user';end if;
 if op='profile' then
  update clqfa_profiles set "displayName"=b->>'displayName',handle=b->>'handle',bio=coalesce(b->>'bio',''),location=coalesce(b->>'location',''),link=coalesce(b->>'link',''),"avatarUri"=b->>'avatarUri' where id=who returning to_jsonb(clqfa_profiles.*) into result;
 elsif op='post' then
  if coalesce(b->>'type','text') not in ('text','images','video') or jsonb_typeof(coalesce(b->'media','[]'))<>'array' then raise exception 'Invalid post';end if;
  if b->>'type'='images' and jsonb_array_length(b->'media') not between 1 and 4 or b->>'type'='video' and jsonb_array_length(b->'media')<>1 or b->>'type'='text' and jsonb_array_length(coalesce(b->'media','[]'))<>0 then raise exception 'Invalid post media';end if;
  insert into clqfa_posts(id,author,type,text,media,parent) values(b->>'id',who,coalesce(b->>'type','text'),coalesce(b->>'text',''),coalesce(b->'media','[]'),b->>'parent') on conflict(id) do nothing;
  select to_jsonb(p) into result from clqfa_posts p where id=b->>'id' and author=who;if result is null then raise exception 'Post identity conflict';end if;
 elsif op='intent' or op='reaction' then
  insert into clqfa_mutations(id,actor) values(b->>'id',who) on conflict do nothing;fresh=found;
  if fresh then
   if op='reaction' then
    select * into m from clqfa_messages where id=b->>'message' and not tombstone and (expires_at is null or expires_at>clock_timestamp());
    if m.id is null or not exists(select 1 from clqfa_members where chat=m.chat and actor=who and active) then raise exception 'Conversation access denied';end if;
    if length(b->>'emoji')>32 then raise exception 'Invalid emoji';end if;
    if b->>'emoji' in ('','none') then delete from clqfa_reactions where message=m.id and actor=who;else insert into clqfa_reactions values(m.id,who,b->>'emoji') on conflict(message,actor) do update set emoji=excluded.emoji;end if;
   elsif b->>'kind'='follow' then
    select id into target_id from clqfa_profiles where handle=b->>'target';if target_id is null or target_id=who then raise exception 'Invalid follow target';end if;
    if b->>'state'='set' then insert into clqfa_follows(actor,target) values(who,target_id) on conflict do nothing;elsif b->>'state'='clear' then delete from clqfa_follows where actor=who and target=target_id;else raise exception 'Invalid set state';end if;
   elsif b->>'kind'='like' then
    if b->>'state'='set' then insert into clqfa_likes(actor,post) values(who,b->>'target') on conflict do nothing;elsif b->>'state'='clear' then delete from clqfa_likes where actor=who and post=b->>'target';else raise exception 'Invalid set state';end if;
   elsif b->>'kind'='repost' then
    if b->>'state'='set' then insert into clqfa_reposts(actor,post) values(who,b->>'target') on conflict do nothing;elsif b->>'state'='clear' then delete from clqfa_reposts where actor=who and post=b->>'target';else raise exception 'Invalid set state';end if;
   else raise exception 'Invalid intent';end if;
  end if;result='{"ok":true}';
 elsif op='chat' then
  select id into target_id from clqfa_profiles where handle=b->>'other';if target_id is null or target_id=who then raise exception 'Choose another person';end if;
  if coalesce(b->>'type','dm')='dm' then
   pair_key=least(who::text,target_id::text)||':'||greatest(who::text,target_id::text);
   insert into clqfa_chats(id,type,pair) values(b->>'id','dm',pair_key) on conflict do nothing;select * into c from clqfa_chats where pair=pair_key;
  elsif b->>'type'='group' then
   if length(b->>'name') not between 1 and 50 then raise exception 'Invalid group name';end if;
   insert into clqfa_chats(id,type,name,description) values(b->>'id','group',b->>'name',coalesce(b->>'description','')) on conflict do nothing;fresh=found;select * into c from clqfa_chats where id=b->>'id';
   if not fresh then if not exists(select 1 from clqfa_members where chat=c.id and actor=who and active) then raise exception 'Conversation access denied';end if;return to_jsonb(c);end if;
  else raise exception 'Invalid chat type';end if;
  insert into clqfa_members(chat,actor,role) values(c.id,who,'admin'),(c.id,target_id,'member') on conflict do nothing;result=to_jsonb(c);
 elsif op='member' then
  select * into c from clqfa_chats where id=b->>'chat' and type='group' for update;
  if c.id is null or not exists(select 1 from clqfa_members where chat=c.id and actor=who and active and (b->>'operation'='leave' or role='admin')) then raise exception 'Conversation access denied';end if;
  if b->>'operation'='leave' then target_id=who;else select id into target_id from clqfa_profiles where handle=b->>'target';end if;if target_id is null then raise exception 'Unknown person';end if;
  if b->>'operation'='add' then
   if exists(select 1 from clqfa_members where chat=c.id and actor=target_id and active) then return '{"ok":true}';end if;
   if (select count(*) from clqfa_members where chat=c.id and active)>=50 then raise exception 'Group is full';end if;
   insert into clqfa_members(chat,actor,role) values(c.id,target_id,'member') on conflict(chat,actor) do update set active=true,role='member';
  elsif b->>'operation'='promote' then update clqfa_members set role='admin' where chat=c.id and actor=target_id and active;
  elsif b->>'operation' in ('remove','leave') then update clqfa_members set active=false where chat=c.id and actor=target_id;
  else raise exception 'Invalid member operation';end if;result='{"ok":true}';
 elsif op='poll-vote' then
  if jsonb_typeof(b->'id') is distinct from 'string' or length(b->>'id') not between 1 and 200 then raise exception 'Mutation id required';end if;
  select * into m from clqfa_messages where id=b->>'message' for update;
  if m.id is null or m.type<>'poll' or m.tombstone or m.expires_at<=clock_timestamp() or not exists(select 1 from clqfa_members where chat=m.chat and actor=who and active) then raise exception 'Poll access denied';end if;
  if not exists(select 1 from jsonb_array_elements(m.poll_options) x where x->>'id'=b->>'option') then raise exception 'Unknown poll option';end if;
  insert into clqfa_poll_intents(actor,id,message,option_id) values(who,b->>'id',m.id,b->>'option') on conflict do nothing;fresh=found;
  if not fresh and not exists(select 1 from clqfa_poll_intents where actor=who and id=b->>'id' and message=m.id and option_id=b->>'option') then raise exception 'Mutation identity conflict';end if;
  if fresh then insert into clqfa_poll_votes(message,actor,option_id) values(m.id,who,b->>'option') on conflict(message,actor) do update set option_id=excluded.option_id;end if;
  result='{"ok":true}';
 elsif op='message' then
  select * into c from clqfa_chats where id=b->>'chat' for update;if c.id is null or not exists(select 1 from clqfa_members where chat=c.id and actor=who and active) then raise exception 'Conversation access denied';end if;
  select to_jsonb(x) into result from clqfa_messages x where id=b->>'id' and sender=who and chat=c.id;if result is not null then return result;end if;
  msgtype=coalesce(b->>'type','text');media_id=b->>'media';if msgtype not in ('text','image','video','poll') or (b->>'viewOnce')::boolean and msgtype<>'image' then raise exception 'Invalid message type';end if;
  if msgtype in ('text','poll') and media_id is not null then raise exception 'Text cannot attach media';end if;
  if msgtype in ('image','video') then select * into a from clqfa_media where id=media_id and owner=who and not revoked;if a.id is null or length(coalesce(b->>'text',''))>500 then raise exception 'Invalid media message';end if;end if;
  if msgtype='poll' then
   if c.type<>'group' or jsonb_typeof(b->'text') is distinct from 'string' or length(btrim(b->>'text'))=0 or length(b->>'text')>200 then raise exception 'Invalid poll question or group';end if;
   if jsonb_typeof(b->'options') is distinct from 'array' then raise exception 'Invalid poll options';end if;
   if jsonb_array_length(b->'options') not between 2 and 4 then raise exception 'Poll requires 2-4 options';end if;
   if exists(select 1 from jsonb_array_elements(b->'options') x where jsonb_typeof(x->'id') is distinct from 'string' or length(x->>'id') not between 1 and 120 or jsonb_typeof(x->'label') is distinct from 'string' or length(btrim(x->>'label'))=0 or length(x->>'label')>50) or (select count(distinct x->>'id') from jsonb_array_elements(b->'options') x)<>jsonb_array_length(b->'options') then raise exception 'Invalid poll option';end if;
  end if;
  if b->>'quote' is not null and not exists(select 1 from clqfa_messages where id=b->>'quote' and chat=c.id and not tombstone and (expires_at is null or expires_at>clock_timestamp())) then raise exception 'Quoted message unavailable';end if;
  select value into window_config from clqfa_config where key='windows';select (v->>'ttlSeconds')::int into ttl from jsonb_array_elements(window_config->'disappearingOptions') v where v->>'value'=c.disappearing;
  insert into clqfa_messages(id,chat,sender,text,quote,type,media,view_once,expires_at,poll_options) values(b->>'id',c.id,who,coalesce(b->>'text',''),b->>'quote',msgtype,media_id,coalesce((b->>'viewOnce')::boolean,false),case when ttl is null then null else clock_timestamp()+make_interval(secs=>ttl) end,case when msgtype='poll' then b->'options' else null end) returning * into m;
  insert into clqfa_receipts(message,actor) select m.id,actor from clqfa_members where chat=c.id and active and actor<>who;
  if not coalesce((select (value->>'enabled')::boolean from clqfa_config where key='replay'),false) then
   insert into clqfa_push(target,payload) select cm.actor,jsonb_build_object('targetUserId',cm.actor,'chatId',c.id,'senderDisplayName',(select "displayName" from clqfa_profiles where id=who),'preview',case when msgtype='image' then 'Photo' when msgtype='video' then 'Video' else left(m.text,80) end) from clqfa_members cm where cm.chat=c.id and cm.active and cm.actor<>who and not exists(select 1 from clqfa_connections where actor=cm.actor);
  end if;result=to_jsonb(m);
 else raise exception 'Unknown mutation';end if;
 return result;
end $$

create or replace procedure clqfa_replay_batch(run_id text,actions jsonb) language plpgsql as $$
declare item jsonb;result jsonb; principal uuid;
begin
 for item in select value from jsonb_array_elements(actions) loop
  principal=(item->>'actor')::uuid;
  if not exists(select 1 from clqfa_replay_principals p where p.actor=principal and p.expires_at>clock_timestamp() and not exists(select 1 from clqfa_revoked r where r.session_id=p.session_id)) then raise exception 'Replay principal expired or revoked';end if;
  if not exists(select 1 from clqfa_replay_receipts where run=run_id and ordinal=(item->>'ordinal')::int) then
   result=clqfa_mutate(principal,item->>'op',item->'body');
   insert into clqfa_replay_receipts(run,ordinal,actor,verb,result) values(run_id,(item->>'ordinal')::int,principal,item->>'verb',jsonb_build_object('id',result->>'id'));
  end if;
  commit;
  raise notice '%',jsonb_build_object('run',run_id,'ordinal',(item->>'ordinal')::int,'verb',item->>'verb','settled',true)::text;
 end loop;
end $$

create or replace function clqfa_count_visibility() returns trigger language plpgsql as $$begin
 NEW.clqfa_count_visible=not NEW.tombstone and (NEW.expires_at is null or NEW.expires_at>clock_timestamp());return NEW;
end$$

create or replace function clqfa_message_counter() returns trigger language plpgsql as $$begin
 if TG_OP='DELETE' then
  if OLD.clqfa_count_visible then update clqfa_chats set message_count=message_count-1 where id=OLD.chat;end if;return OLD;
 elsif TG_OP='INSERT' then
  if NEW.clqfa_count_visible then update clqfa_chats set message_count=message_count+1 where id=NEW.chat;end if;
 else
  if OLD.chat<>NEW.chat then raise exception 'Message conversation is immutable';end if;
  if OLD.clqfa_count_visible<>NEW.clqfa_count_visible then update clqfa_chats set message_count=message_count+case when NEW.clqfa_count_visible then 1 else -1 end where id=NEW.chat;end if;
 end if;return NEW;
end$$

create policy clqfm_mem_upd on clqfm_members for update to authenticated
  using (clqfm_is_admin(conversation_id, auth.uid()) or auth.uid() = user_id)
  with check (clqfm_is_admin(conversation_id, auth.uid()) or auth.uid() = user_id)

create policy clqfm_msg_sel on clqfm_messages for select to authenticated
  using (clqfm_is_member(conversation_id, auth.uid())
    and not purged and (expires_at is null or expires_at > now()))

create policy clqfm_msg_upd on clqfm_messages for update to authenticated
  using (auth.uid() = sender_id and clqfm_is_member(conversation_id, auth.uid()))
  with check (auth.uid() = sender_id and clqfm_is_member(conversation_id, auth.uid()))

-- ---------- message window enforcement (server time) ----------
create or replace function clqfm_enforce_message_windows()
returns trigger language plpgsql security definer set search_path = public as $$
declare edit_s int; del_s int;
begin
  if NEW.purged then return NEW; end if; -- system purge bypass
  edit_s := coalesce((clqfm_cfg_windows()->>'editWindowSeconds')::int, 900);
  del_s := coalesce((clqfm_cfg_windows()->>'deleteForEveryoneWindowSeconds')::int, 3600);
  if TG_OP = 'UPDATE' then
    if (NEW.body is distinct from OLD.body) and not NEW.deleted and not OLD.deleted then
      if extract(epoch from (now() - OLD.created_at)) > edit_s then
        raise exception 'CLQFM_EDIT_WINDOW_EXCEEDED';
      end if;
      NEW.edited := true; NEW.edited_at := now();
    end if;
    if NEW.deleted and not OLD.deleted then
      if extract(epoch from (now() - OLD.created_at)) > del_s then
        raise exception 'CLQFM_DELETE_WINDOW_EXCEEDED';
      end if;
      NEW.deleted_at := now();
    end if;
  end if;
  return NEW;
end $$

-- ---------- counters ----------
create or replace function clqfm_bump_counters()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if TG_TABLE_NAME = 'clqfm_likes' then
    if TG_OP = 'INSERT' then update clqfm_posts set like_count = like_count + 1 where id = NEW.post_id;
    else update clqfm_posts set like_count = greatest(like_count - 1, 0) where id = OLD.post_id; end if;
  elsif TG_TABLE_NAME = 'clqfm_reposts' then
    if TG_OP = 'INSERT' then update clqfm_posts set repost_count = repost_count + 1 where id = NEW.post_id;
    else update clqfm_posts set repost_count = greatest(repost_count - 1, 0) where id = OLD.post_id; end if;
  elsif TG_TABLE_NAME = 'clqfm_posts' then
    if TG_OP = 'INSERT' and NEW.parent_id is not null then
      update clqfm_posts set reply_count = reply_count + 1 where id = NEW.parent_id;
    elsif TG_OP = 'DELETE' and OLD.parent_id is not null then
      update clqfm_posts set reply_count = greatest(reply_count - 1, 0) where id = OLD.parent_id;
    end if;
  end if;
  return coalesce(NEW, OLD);
end $$

-- group admin enforcement for conversation settings (server-side)
create or replace function clqfm_enforce_convo_admin()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if TG_OP = 'UPDATE' and NEW.kind = 'group' then
    if (NEW.name is distinct from OLD.name or NEW.description is distinct from OLD.description
        or NEW.color is distinct from OLD.color or NEW.background_path is distinct from OLD.background_path
        or NEW.disappearing is distinct from OLD.disappearing) then
      if not clqfm_is_admin(OLD.id, auth.uid()) then
        raise exception 'CLQFM_NOT_ADMIN';
      end if;
    end if;
  end if;
  return NEW;
end $$

-- Push-seam trigger, expiry sweeper, digest tick, feed/thread/history/insights/trending RPCs.

-- ---------- push seam: server-side, on message insert ----------
create or replace function clqfm_after_message_insert()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  r record; sname text; preview text; online_cutoff timestamptz;
begin
  if not clqfm_cfg_push_enabled() then return NEW; end if;
  select coalesce(display_name, handle, 'Someone') into sname
    from clqfm_profiles where user_id = NEW.sender_id;
  if NEW.kind = 'text' then preview := left(NEW.body, 80);
  elsif NEW.view_once then preview := 'Photo';
  elsif NEW.kind = 'image' then preview := 'Photo';
  else preview := 'Video'; end if;
  online_cutoff := now() - interval '90 seconds';
  for r in select m.user_id from clqfm_members m
           where m.conversation_id = NEW.conversation_id
             and m.user_id <> NEW.sender_id and m.left_at is null
  loop
    if not exists (select 1 from clqfm_presence p
                   where p.user_id = r.user_id and p.last_seen > online_cutoff) then
      insert into clqfm_push_log (target_user_id, chat_id, sender_name, preview, kind)
      values (r.user_id, NEW.conversation_id, sname, preview, 'message');
    end if;
  end loop;
  return NEW;
end $$

-- ---------- expiry sweeper (pg_cron calls this every minute) ----------
create or replace function clqfm_expire_tick()
returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  update clqfm_messages set purged = true, body = '', media_path = ''
    where not purged and expires_at is not null and expires_at <= now();
  get diagnostics n = row_count;
  return n;
end $$

-- ---------- digest scheduler (pg_cron calls this every minute) ----------
create or replace function clqfm_digest_tick()
returns int language plpgsql security definer set search_path = public as $$
declare
  dcfg jsonb; psecs int; anchor_t time; midnight timestamptz; anchor_ts timestamptz;
  last_done timestamptz; target_start timestamptz; target_end timestamptz;
  u record; nf int; npf int; unm int; unc int; emitted int := 0;
begin
  if not clqfm_cfg_push_enabled() then return 0; end if;
  dcfg := clqfm_cfg_digest();
  psecs := coalesce((dcfg->>'periodSeconds')::int, 86400);
  anchor_t := coalesce((dcfg->>'periodAnchorUtc')::time, time '08:00:00');
  midnight := date_trunc('day', now());
  anchor_ts := midnight + anchor_t;
  if anchor_ts > now() then anchor_ts := anchor_ts - interval '1 day'; end if;
  -- last fully completed period start: periods are [anchor + k*p, anchor + (k+1)*p), emit when end <= now
  target_start := anchor_ts + make_interval(secs => ((extract(epoch from (now() - anchor_ts))::bigint / psecs) - 1) * psecs);
  target_end := target_start + make_interval(secs => psecs);
  if target_end > now() then return 0; end if;
  select watermark into last_done from clqfm_digest_state where id = 1;
  if last_done is not null and target_start <= last_done then return 0; end if;
  for u in select user_id from clqfm_profiles loop
    select count(*) into nf from clqfm_follows
      where followee_id = u.user_id and created_at >= target_start and created_at < target_end;
    select count(*) into npf from clqfm_posts p
      where p.parent_id is null and p.created_at >= target_start and p.created_at < target_end
        and (p.author_id = u.user_id or exists (select 1 from clqfm_follows f
          where f.follower_id = u.user_id and f.followee_id = p.author_id));
    select count(*), count(distinct m.conversation_id) into unm, unc from clqfm_messages m
      join clqfm_members mb on mb.conversation_id = m.conversation_id
      where mb.user_id = u.user_id and mb.left_at is null
        and m.sender_id <> u.user_id and not m.deleted and not m.purged
        and (m.expires_at is null or m.expires_at > now())
        and m.created_at >= target_start and m.created_at < target_end
        and not exists (select 1 from clqfm_receipts r
          where r.message_id = m.id and r.user_id = u.user_id and r.state = 'read');
    if nf + npf + unm + unc = 0 then continue; end if;
    insert into clqfm_digest_sent (period_start, user_id)
      values (target_start, u.user_id) on conflict do nothing;
    if found then
      insert into clqfm_push_log (target_user_id, kind, period_start, period_end,
        new_followers, new_posts_following, unread_messages, unread_chats)
      values (u.user_id, 'digest', target_start, target_end, nf, npf, unm, unc);
      emitted := emitted + 1;
    end if;
  end loop;
  insert into clqfm_digest_state (id, watermark) values (1, target_start)
    on conflict (id) do update set watermark = excluded.watermark;
  return emitted;
end $$

create or replace function clqfm_maintain_message_count()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  old_vis boolean; new_vis boolean;
begin
  if TG_OP = 'INSERT' then
    if clqfm_msg_visible(NEW.deleted, NEW.purged, NEW.expires_at) then
      update clqfm_conversations set message_count = message_count + 1
        where id = NEW.conversation_id;
    end if;
    return NEW;
  elsif TG_OP = 'DELETE' then
    if clqfm_msg_visible(OLD.deleted, OLD.purged, OLD.expires_at) then
      update clqfm_conversations set message_count = greatest(message_count - 1, 0)
        where id = OLD.conversation_id;
    end if;
    return OLD;
  else
    old_vis := clqfm_msg_visible(OLD.deleted, OLD.purged, OLD.expires_at);
    new_vis := clqfm_msg_visible(NEW.deleted, NEW.purged, NEW.expires_at);
    if old_vis and not new_vis then
      update clqfm_conversations set message_count = greatest(message_count - 1, 0)
        where id = NEW.conversation_id;
    elsif new_vis and not old_vis then
      update clqfm_conversations set message_count = message_count + 1
        where id = NEW.conversation_id;
    end if;
    return NEW;
  end if;
end $$

create trigger clqfm_trg_msg_count
  after insert or update of deleted, purged, expires_at or delete on clqfm_messages
  for each row execute function clqfm_maintain_message_count()

-- ============ 2d. expiry sweeper reconciles counts ============
-- No trigger fires when expires_at merely passes now(), so an expiry would
-- leak its +1 until purge (whose OLD row already reads invisible, hence no
-- delta either). The sweeper therefore recounts every conversation it
-- purges — an absolute set that heals the gap by construction. (Between
-- expiry and the next minute-tick the stored count reads stale-high by the
-- newly expired rows; history already excludes them. Known transient,
-- documented in m7/final-report.md.)

create or replace function clqfm_expire_tick()
returns int language plpgsql security definer set search_path = public as $$
declare
  n int := 0;
  affected text[] := '{}';
  r record;
  cid text;
begin
  for r in update clqfm_messages set purged = true, body = '', media_path = ''
    where not purged and expires_at is not null and expires_at <= now()
    returning conversation_id
  loop
    n := n + 1;
    if not (r.conversation_id = any(affected)) then
      affected := affected || r.conversation_id;
    end if;
  end loop;
  foreach cid in array affected loop
    update clqfm_conversations c set message_count = coalesce((
      select count(*) from clqfm_messages m
      where m.conversation_id = cid
        and not m.deleted and not m.purged
        and (m.expires_at is null or m.expires_at > now())
    ), 0) where c.id = cid;
  end loop;
  return n;
end $$

-- ============ 1c. poll read model ============

create or replace function clqfm_poll_state(viewer uuid, msg text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  m record; opts jsonb; total int; mine text;
begin
  select * into m from clqfm_messages where id = msg;
  if m.id is null then raise exception 'CLQFM_UNKNOWN_MESSAGE'; end if;
  if m.kind <> 'poll' then return null; end if;
  if not clqfm_ever_member(m.conversation_id, viewer) then
    raise exception 'CLQFM_NOT_A_MEMBER';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', o.option_id, 'label', o.label, 'tally',
      (select count(*) from clqfm_poll_votes v
        where v.message_id = o.message_id and v.option_id = o.option_id))
    order by o.position), '[]'::jsonb)
    into opts
    from clqfm_poll_options o where o.message_id = msg;
  select count(*) into total from clqfm_poll_votes where message_id = msg;
  select option_id into mine from clqfm_poll_votes
    where message_id = msg and user_id = viewer;
  return jsonb_build_object(
    'question', m.body, 'options', opts, 'total', total, 'myOption', mine);
end $$

-- ============ 1d. poll creation (group-only, validated) ============

create or replace function clqfm_create_poll(viewer uuid, convo text, question text, options jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  c record; q text; n int; i int; label text;
  mid text; ttl bigint; exp timestamptz := null; oids text[] := '{}';
begin
  select * into c from clqfm_conversations where id = convo;
  if c.id is null then raise exception 'CLQFM_UNKNOWN_CONVERSATION'; end if;
  if c.kind <> 'group' then raise exception 'CLQFM_POLLS_GROUP_ONLY'; end if;
  if not clqfm_is_member(convo, viewer) then
    raise exception 'CLQFM_NOT_A_MEMBER';
  end if;
  q := btrim(coalesce(question, ''));
  if char_length(q) = 0 or char_length(q) > 200 then
    raise exception 'CLQFM_BAD_QUESTION';
  end if;
  if jsonb_typeof(options) <> 'array' then raise exception 'CLQFM_BAD_OPTIONS'; end if;
  n := jsonb_array_length(options);
  if n < 2 or n > 4 then raise exception 'CLQFM_BAD_OPTIONS'; end if;
  for i in 0..n-1 loop
    label := btrim(coalesce(options->>i, ''));
    if char_length(label) = 0 or char_length(label) > 50 then
      raise exception 'CLQFM_BAD_OPTION';
    end if;
  end loop;
  ttl := clqfm_disappearing_ttl(c.disappearing);
  if ttl is not null and ttl > 0 then exp := now() + make_interval(secs => ttl); end if;
  mid := 'poll-' || substr(md5(random()::text || clock_timestamp()::text), 1, 16);
  insert into clqfm_messages (id, conversation_id, sender_id, kind, body,
    media_path, view_once, quote_id, expires_at)
    values (mid, convo, viewer, 'poll', q, '', false, null, exp);
  for i in 0..n-1 loop
    label := btrim(options->>i);
    oids := oids || (mid || '-o' || (i + 1)::text);
    insert into clqfm_poll_options (message_id, option_id, label, position)
      values (mid, mid || '-o' || (i + 1)::text, label, i + 1);
  end loop;
  return jsonb_build_object('message_id', mid, 'option_ids', to_jsonb(oids));
end $$

-- ============ 1e. idempotent set-state vote ============

create or replace function clqfm_vote_poll(viewer uuid, msg text, opt text, mut text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  m record;
begin
  if mut is null or btrim(mut) = '' then raise exception 'CLQFM_BAD_MUTATION'; end if;
  -- Validate first (read-only): a rejected intent must not burn its
  -- mutation id, or a later corrected retry with the same id would no-op.
  select * into m from clqfm_messages where id = msg;
  if m.id is null then raise exception 'CLQFM_UNKNOWN_MESSAGE'; end if;
  if m.kind <> 'poll' then raise exception 'CLQFM_NOT_A_POLL'; end if;
  if not clqfm_is_member(m.conversation_id, viewer) then
    raise exception 'CLQFM_NOT_A_MEMBER';
  end if;
  if not exists (select 1 from clqfm_poll_options o
                 where o.message_id = msg and o.option_id = opt) then
    raise exception 'CLQFM_UNKNOWN_OPTION';
  end if;
  -- Idempotency ledger: a mutation id already recorded (applied now or
  -- superseded later by a newer intent) is a replay — return current state
  -- without writing, so retry can never flip state.
  insert into clqfm_poll_mutations (mutation_id, message_id, user_id)
    values (mut, msg, viewer)
  on conflict (mutation_id) do nothing;
  if not found then
    return clqfm_poll_state(viewer, msg);
  end if;
  insert into clqfm_poll_votes (message_id, user_id, option_id, mutation_id)
    values (msg, viewer, opt, mut)
  on conflict (message_id, user_id)
    do update set option_id = excluded.option_id,
      mutation_id = excluded.mutation_id, created_at = now();
  return clqfm_poll_state(viewer, msg);
exception when unique_violation then
  -- Lost a race with our own retry (same mutation id landed first):
  -- the intent is applied; report current state unchanged.
  return clqfm_poll_state(viewer, msg);
end $$

-- ============ 1g. poll push preview (question text, like text messages) ============

create or replace function clqfm_after_message_insert()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  r record; sname text; preview text; online_cutoff timestamptz;
begin
  if not clqfm_cfg_push_enabled() then return NEW; end if;
  select coalesce(display_name, handle, 'Someone') into sname
    from clqfm_profiles where user_id = NEW.sender_id;
  if NEW.kind = 'text' then preview := left(NEW.body, 80);
  elsif NEW.kind = 'poll' then preview := left(NEW.body, 80);
  elsif NEW.view_once then preview := 'Photo';
  elsif NEW.kind = 'image' then preview := 'Photo';
  else preview := 'Video'; end if;
  online_cutoff := now() - interval '90 seconds';
  for r in select m.user_id from clqfm_members m
           where m.conversation_id = NEW.conversation_id
             and m.user_id <> NEW.sender_id and m.left_at is null
  loop
    if not exists (select 1 from clqfm_presence p
                   where p.user_id = r.user_id and p.last_seen > online_cutoff) then
      insert into clqfm_push_log (target_user_id, chat_id, sender_name, preview, kind)
      values (r.user_id, NEW.conversation_id, sname, preview, 'message');
    end if;
  end loop;
  return NEW;
end $$
